package app.streamnest;
import android.content.*;import android.os.SystemClock;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicReference;import org.json.*;
/** Separate owner-visible current activity. Never writes titles into diagnostic logs or a local queue file. */
final class WatchingActivity {
 private static Context context;private static java.lang.ref.WeakReference<android.app.Activity> active=new java.lang.ref.WeakReference<>(null);private static Pending sent;private static long lastAttempt;
 private static final AtomicReference<Pending> latest=new AtomicReference<>();
 private static final ScheduledExecutorService worker=Executors.newSingleThreadScheduledExecutor(r->new Thread(()->{android.os.Process.setThreadPriority(android.os.Process.THREAD_PRIORITY_BACKGROUND);r.run();},"watching-activity"));
 private static final class Pending {final String code;final JSONObject activity;final long observed=SystemClock.elapsedRealtime();Pending(String code,JSONObject activity){this.code=code;this.activity=activity;}}
 static boolean enabled(Context c){return c.getSharedPreferences("watching-activity",0).getBoolean("enabled",true);}
 private static String code(Context c){try{return WatchSync.code(c);}catch(Exception e){return "";}}
 static synchronized void install(Context c){if(context!=null)return;context=c.getApplicationContext();worker.scheduleWithFixedDelay(WatchingActivity::drain,2,5,TimeUnit.SECONDS);}
 static void begin(android.app.Activity activity){active=new java.lang.ref.WeakReference<>(activity);report(activity,"starting");}
 static void report(android.app.Activity activity,String state){install(activity);if(active.get()!=activity||!enabled(activity)||activity.isFinishing()&&!state.equals("stopped"))return;String code=code(activity);if(code.isEmpty())return;if(!activity.getSharedPreferences("watching-activity",0).getBoolean("noticeShown",false)){activity.getSharedPreferences("watching-activity",0).edit().putBoolean("noticeShown",true).apply();new android.os.Handler(android.os.Looper.getMainLooper()).post(()->android.widget.Toast.makeText(activity.getApplicationContext(),"Watching activity sharing is on. The dashboard owner can see titles and episodes. Change it in Playback & storage.",android.widget.Toast.LENGTH_LONG).show());}Intent i=activity.getIntent();try{String title=i.getStringExtra("activityTitle"),kind=i.getStringExtra("activityKind");if(title==null||title.trim().isEmpty())return;JSONObject value=new JSONObject().put("title",title).put("kind",kind).put("state",state);if(!"movies".equals(kind))value.put("season",i.getIntExtra("season",0)).put("episode",i.getIntExtra("episode",0));value=WatchingPayload.clean(value);if(value!=null)latest.set(new Pending(code,value));}catch(Exception ignored){}}
 static void setEnabled(Context c,boolean on){install(c);c.getSharedPreferences("watching-activity",0).edit().putBoolean("enabled",on).apply();if(!on)reset(c);}
 static void reset(Context c){install(c);String old=code(c);latest.set(null);sent=null;worker.execute(()->{if(old.isEmpty())return;try{call(old,"DELETE",new JSONObject().put("deviceId",SyncGroup.deviceId(c)));}catch(Exception ignored){}});}
 private static void call(String code,String method,JSONObject value)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(WatchSync.endpoint(context)+"/v1/activity").openConnection();c.setConnectTimeout(8000);c.setReadTimeout(10000);c.setInstanceFollowRedirects(false);c.setRequestMethod(method);c.setRequestProperty("Authorization","Bearer "+WatchSyncCrypto.auth(code));c.setRequestProperty("Content-Type","application/json");byte[] bytes=value.toString().getBytes(StandardCharsets.UTF_8);c.setFixedLengthStreamingMode(bytes.length);c.setDoOutput(true);try{try(OutputStream out=c.getOutputStream()){out.write(bytes);}int status=c.getResponseCode();if(status==410)throw new GroupDeletedException();if(status!=200)throw new IOException("Activity HTTP "+status);try(InputStream in=c.getInputStream()){Net.read(in,2048);}}finally{c.disconnect();}}
 private static void drain(){Pending p=latest.get();if(context==null||p==null||p==sent||!enabled(context)||!p.code.equals(code(context))||SystemClock.elapsedRealtime()-lastAttempt<10000)return;lastAttempt=SystemClock.elapsedRealtime();try{if(SyncGroup.current==null)SyncGroup.update(context,null);if(!enabled(context)||!p.code.equals(code(context))||p!=latest.get())return;long age=Math.max(0,SystemClock.elapsedRealtime()-p.observed);if(age>=86400000){latest.compareAndSet(p,null);return;}call(p.code,"PUT",new JSONObject().put("deviceId",SyncGroup.deviceId(context)).put("sharing",true).put("ageMs",age).put("activity",p.activity));sent=p;}catch(GroupDeletedException e){WatchSync.deleted(context,p.code);}catch(Exception ignored){/* Current activity retries separately; playback and encrypted sync never wait. */}}
}
